// Authored technical narratives, selected by implementation rather than JSON shape.
// Source values are interpolated explicitly; no property-to-chapter fallback.
import fs from 'node:fs';
import {hash} from '../server/model.js';
const read=p=>JSON.parse(fs.readFileSync(p));
const original=read('data_storytelling/review_evidence/root-technical-specifications/proposals.json').change;
const previousFile='data_storytelling/review_evidence/technical-narrative-refinement/proposals.json';
const previousAuthored=fs.existsSync(previousFile)?read(previousFile).change:[];
const source=r=>r.technical_definition||r.composition_history[0].technical_definition;
const clean=s=>s.toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'');
const join=xs=>xs.length<2?xs[0]||'':xs.slice(0,-1).join(', ')+' and '+xs.at(-1);
class Narrative{
 constructor(r){this.r=r;this.chapters=[];this.parameters=[];this.references=new Map();}
 p(key,value){if(Array.isArray(value))value=value.join(', ');const old=this.parameters.find(p=>p.key===key);if(old&&old.value!==value)throw Error(this.r.id+' conflicting '+key);if(!old)this.parameters.push({key,value});return '{'+key+'}';}
 ref(key,id,role){if(id===this.r.id)return this.r.name;if(this.references.has(id))return '{'+this.references.get(id)+'}';if(this.parameters.some(p=>p.key===key))throw Error('Duplicate key '+key);this.references.set(id,key);this.parameters.push({key,ref_id:id,ref_role:role});return '{'+key+'}';}
 refs(ids,role,prefix=''){return join([...new Set(ids)].map(id=>this.ref(prefix+clean(id.split('.').slice(1).join('_')),id,role)));}
 c(chapter_name,...paragraphs){const description=paragraphs.filter(Boolean).join('\n\n');if(description)this.chapters.push({number:this.chapters.length+1,chapter_name,description});}
 done(){const prose=this.chapters.map(c=>c.description).join('\n');this.parameters=this.parameters.filter(p=>prose.includes('{'+p.key+'}'));return {chapters:this.chapters,parameters:this.parameters};}
}
function monitor(n,s){
 const c=s.capabilities,grey=c.color_model==='grayscale',controller=n.ref('controller_id',s.controller_id,'Converts digital pixel indices into the monitor’s output levels');
 const display=n.ref('display_assembly_id',s.crt_id||s.display_subassembly_id,s.crt_id?'CRT used by this monitor':'OEM display assembly adapted for this monitor');
 const levels=s.intensity_levels||s.displayed_registers||s.displayed_color_registers;
 n.c('Display and signal path',`The monitor combines ${display} with ${controller} to display ${n.p('displayed_levels',levels)} ${grey?'grayscale levels':'palette-selected colours'} from Logix’s 4-bit digital video signal. ${c.programmable_palette?`Its programmable palette uses ${n.p('palette_precision_bits',c.palette_precision_bits)}-bit ${grey?'intensity':'RGB'} values.`:'The fixed intensity conversion does not provide a programmable palette.'}`,s.analog_chain||'');
 const rasters=c.raster_ids.map(x=>x.replace('raster_','').replace('_',' × ')).join(', '),preferred=c.preferred_raster_id.replace('raster_','').replace('_',' × ');
 n.c('Raster compatibility',`Capability protocol version ${n.p('capability_protocol_version',c.protocol_version)} advertises ${n.p('raster_profiles',rasters)} ${c.raster_ids.length===1?'as its supported and preferred raster':`raster profiles, preferring ${n.p('preferred_raster',preferred)}`}. The maximum pixel clock is ${n.p('maximum_pixel_clock_mhz',c.maximum_pixel_clock_mhz)} MHz.`,s.mode_limit||'',s.scan?c.raster_ids[0]==='raster_640_400'?'The display uses fixed-frequency progressive scanning; older logical modes must be scaled by the card.':'':'',s.palette_list_id?`Horizontal-retrace palette updates follow ${n.ref('palette_list_id',s.palette_list_id,'Protocol for scanline palette updates')}. The 64 KiB card executes these lists; an earlier 32 KiB card can provide static or vertical-retrace colour after monitor identification support. The Color Pro timing target is 26.88 kHz horizontal at 60 Hz.`:'');
}
function network(n,t){
 const s=t.specification,art=n.r.id==='device.network_card_artemis';
 n.c('Host connection and purpose',art?`This removable 32-bit Plug and Execute adapter occupies one general-purpose slot on ${n.refs(t.compatible_with,'Host covered by this adapter’s rate profile','host_')}. It is fitted to networking-era systems and can upgrade earlier Artemis computers; electrical implementation remains open. Artemis PRO supports the server role.`:`This adapter connects ${n.refs(t.compatible_with,'Host covered by this adapter’s rate profile','host_')} to Logix LAN.`,art?`The same baseline is planned for ${n.refs(t.planned_compatible_with,'Planned host; electrical and firmware qualification remain open','planned_')}, subject to host qualification.`:'');
 const link=n.ref('link_protocol_id',s.link_layer_id,'Negotiation and shared-medium protocol implemented by the adapter'),tcp=n.ref('tcpip_stack_id','technology.logix_tcpip_lan','Network stack carried over this adapter');
 n.c('Rates and shared-medium operation',`The adapter carries ${tcp} over ${link}. Discovery starts at ${n.p('startup_rate_kbps',s.startup_rate_kbps)} kbit/s. ${art?`Both recorded hosts support ${n.p('supported_rates_kbps',s.platform_rate_profiles[0].supported_rates_kbps)} kbit/s.`:`Aurelia supports ${n.p('aurelia_rates_kbps',s.platform_rate_profiles[0].supported_rates_kbps)} kbit/s; Aurelia+ supports ${n.p('aurelia_plus_rates_kbps',s.platform_rate_profiles[1].supported_rates_kbps)} kbit/s.`} Firmware enforces each host’s highest listed rate as its ceiling. The negotiated common rate must also satisfy every admitted station and qualified link.`,s.adapter_requirements.flow_control);
 n.c('Packet buffering and host service',`Hardware performs framing and CRC checks, rejects frames for other destinations before interrupting the CPU, buffers complete frames, and reports receiver readiness through packet-level interrupts. Local packet RAM targets ${n.p('packet_ram_target_bytes',s.local_packet_ram_target_bytes)} bytes in addition to system RAM. Its chip population remains unresolved; transmit/receive partitions, metadata, maximum frame length and IP MTU must be qualified together.`,art?'The host must service packets within a validated worst-case latency without per-byte interrupts. A persistently slow host may advertise a lower configured ceiling.':`At the respective host ceilings, Aurelia has 128 CPU clocks per raw byte at 4 MHz and Aurelia+ has 96 at 6 MHz. These budgets require worst-case service-latency testing; a persistently slow host may advertise a lower configured ceiling.`);
}
function graphics(n,s,kind='card'){
 const chip=kind==='chip';
 n.c(chip?'Display-controller architecture':'Display architecture',`${chip?'The controller':'The card uses '+n.ref('graphics_controller_id',s.controller_id,'Graphics controller fitted to this card')+' and'} implements ${n.ref('video_link_id',s.technology_id,'Digital display signal protocol')} through ${n.ref('display_api_id',s.api_id,'Mode discovery and display-memory contract')}. Software selects only modes supported by the controller, monitor profile and available buffer/sprite allocation; unsupported downscaling is rejected.`,s.feature_continuity_id?`It extends ${n.ref('previous_card_id',s.feature_continuity_id,'Baseline whose modes and host/API features are retained')}; ${n.ref('palette_list_id',s.palette_list_id,'Bounded horizontal-retrace palette update mechanism')} adds scanline palette changes.`:'',s.card_id?`The corresponding board is ${n.ref('card_id',s.card_id,'Board implementing this controller’s recorded memory arrangement')}; external RAM populations below describe that board rather than memory integrated on the die.`:'');
 const d=s.display_memory,sp=s.sprite_memory;
 n.c('Display memory and sprites',`Display storage is ${n.p('video_ram_kib',s.video_ram_kb)} KiB, built from ${n.p('display_chip_count',d.chip_count)} ${n.ref('display_chip_id',d.chip_id,'External DRAM used for display storage')} devices on a ${n.p('display_bus_bits',d.bank_data_width_bits)}-bit bus. ${s.video_ram_kb===64?'Two 16K × 16-bit banks use ordinary DRAM, not dual-port VRAM. ':''}Text/font and bitmap allocations are alternative uses of this memory. Sprite storage is independent: ${n.p('sprite_ram_bytes',sp.capacity_bytes)} bytes from ${n.p('sprite_chip_count',sp.chip_count)} ${n.ref('sprite_chip_id',sp.chip_id,'SRAM dedicated to sprite data')} chips on a separate ${n.p('sprite_bus_bits',sp.bank_data_width_bits)}-bit bus.`,s.video_ram_kb===64?'When palette lists are enabled, reserve 0xFA00–0xFFFF (1536 bytes); text, fonts and framebuffers occupy 0x0000–0xF9FF.':'',s.memory_layout.font_policy,'Page selection latches during vertical blank. Double buffering does not guarantee drawing throughput.',s.sprite_profile_ref?`Sprite geometry and compositing follow ${n.ref('sprite_protocol_id',s.sprite_profile_ref.technology_id,'Sprite semantics implemented by the controller')} ${n.p('sprite_profile',s.sprite_profile_ref.profile)}.`:'');
 pixelPipeline(n,s);
 n.c('Memory arbitration and display qualification',s.arbitration,s.timing_budget?.qualification||'',s.monitor_policy,s.host_interface?`The host’s ${n.p('host_bus_bits',s.host_interface.host_width_bits)}-bit interface is bridged to the local display bus using byte enables, staging latches and bounded READY/backpressure. A word upload can require four local transfers; the board is not hot-swappable.`:'');
 if(s.sprites){const x=s.sprites;n.c('Sprite composition',`Up to ${n.p('sprite_count',x.count)} sprites can appear on each scanline. Each is ${n.p('sprite_size',`${x.width} × ${x.height}`)} pixels at ${n.p('sprite_bits_per_pixel',x.bits_per_pixel)} bits per pixel, with index ${n.p('transparent_index',x.transparent_index)} transparent. Lower sprite numbers take priority over higher ones, and all overlay text or background. Signed 16-bit logical coordinates scale with the background and clip at screen edges.`,`Five patterns occupy 640 bytes. Two banks of 8-byte descriptors use 80 live bytes within a 128-byte reservation, leaving 48 bytes of padding and 256 bytes of scratch space in sprite SRAM. Auto-increment upload ports accept CPU/DMA transfers. Descriptors are banked; patterns are not double-buffered. All sprites remain available when the background is double-buffered.`);}
 if(s.die_area_planning_mm2)n.chapters[0].description+=` The controller has a planning die area of ${n.p('die_area_mm2',s.die_area_planning_mm2)} mm², not a measured production die.`;
}
function pixelPipeline(n,s){
 const b=s.pixel_buffer,c=s.character_row_cache,large=b.bytes_per_page===160;
 n.c('Scanout pipeline',`The ${s.video_ram_kb===16?'Aurelia-derived':'ASIC'} pixel pipeline contains ${n.p('pixel_buffer_pages',b.pages)} banks of ${n.p('pixel_buffer_page_bytes',b.bytes_per_page)} bytes, holding ${n.p('pixel_depth_bits',b.bits_per_pixel)}-bit pixels. Separate ownership states prevent the renderer from overwriting a bank being scanned out: ${n.p('pixel_bank_states',b.page_states||['free','filling','ready','reading'])}. Completed banks feed output latches and a serializer; the pipeline is prefetched before active display and preserves sync on underrun.`,large?'Each bank comprises 40 × 32-bit words and holds 320 pixels, so a 640-pixel line consumes two banks. The renderer expands eight pixels at a time while a separate serializer latch drains ready banks. Underrun blanks pixels and sets a sticky fault.':'The FIFO sits inside the reused Aurelia controller; it is not another framebuffer.',`Two ${n.p('character_cache_bytes',c.bytes_per_bank)}-byte row caches hold current and next character/attribute rows independently of the pixel FIFO.`,s.timing_budget?`The dot clock is ${n.p('pixel_clock_mhz',s.timing_budget.pixel_clock_mhz)} MHz. Eight-pixel renderer steps and SRAM latch loads run at ${n.p('renderer_step_mhz',s.timing_budget.renderer_step_mhz)} MHz, rather than requiring one SRAM read per dot. A pixel bank drains in ${n.p('pixel_bank_drain_us',s.timing_budget.page_drain_microseconds)} µs.`:large?'The serializer shifts at 21.504 MHz, loading eight pixels every eight dot clocks; SRAM latch reads therefore run at 2.688 MHz with filler and drain on different banks.':'');
}
function device(n,t){
 const s=t.specification||{},id=n.r.id;
 if(s.capabilities){monitor(n,s);return;}
 if(id==='device.network_card_aurelia'||id==='device.network_card_artemis'){network(n,t);return;}
 if(id.startsWith('device.network_hub.')){n.c('Shared-rate LAN repeater',`This active-star repeater connects ${n.p('port_count',s.port_count)} stations using ${n.ref('link_protocol_id',s.negotiation_id,'Station discovery, rate negotiation and transmit-grant protocol')}. The supported raw rates are ${n.p('supported_rates_kbps',s.supported_rates_kbps)} kbit/s, with discovery beginning at the lowest rate. All admitted stations share one negotiated rate and one transmitter at a time; additional ports do not multiply bandwidth.`,`The arbiter grants transmission only when the intended receivers have complete-frame credit. It coordinates discovery, link qualification and fallback while repeating traffic at the common rate. Application throughput is lower than raw line rate and remains unvalidated.`);return;}
 if(['device.artemis_video_card','device.artemis_video_card_16kb','device.artemis_video_card_64kb'].includes(id)){graphics(n,s);if(t.planned_compatible_with)n.chapters.at(-1).description+=`\n\nUse on ${n.refs(t.planned_compatible_with,'Planned host for the selected graphics-card baseline','planned_')} requires electrical and firmware qualification; selection of the existing baseline does not establish that these hosts are ready.`;return;}
 if(id.startsWith('device.base_computer.')){computer(n,t);return;}
 if(s.chip_type_id){n.c('Memory organization',`This module provides ${n.p('capacity_kb',s.capacity_kb)} KiB from ${n.p('chips',s.chips)} ${n.ref('chip_type_id',s.chip_type_id,'DRAM chip used to populate this module')} chips on a ${n.p('data_width_bits',s.data_width_bits)}-bit interface. ${s.physical_arrangement?`The chips are physically arranged as ${n.p('physical_arrangement',s.physical_arrangement)}.`:`Each chip is organized as ${n.p('chip_organization',s.chip_organization)}. The module has ${n.p('ranks',s.ranks)} rank${s.ranks===1?'':'s'}, each containing ${n.p('chips_per_rank',s.chips_per_rank)} chips and ${n.p('rank_capacity_kib',s.rank_capacity_kb)} KiB.`}`,t.compatible_with?`The recorded host is ${n.refs(t.compatible_with,'Host for this memory-module design','host_')}.`:'');if(s.modules_per_bank)n.c('Bank installation and qualification',`Install matched pairs with power off: ${n.p('modules_per_bank',s.modules_per_bank)} independently selected modules form a ${n.p('bank_capacity_kib',s.bank_capacity_kb)} KiB capacity bank on the shared ${n.p('bank_data_width_bits',s.bank_data_width_bits)}-bit bus. The pair adds addressable capacity rather than concatenating data lanes. No parity bits are fitted.`,`The controller must decode every installed module and rank and refresh all arrays. Artemis/Athena connector, rank selection, power, timing and loading qualification remain open for each controller.`);return;}
 if(id==='device.flexibus_keyboard'){n.c('Keyboard layout and interface',`The keyboard connects over ${n.p('connection',t.connection)} and provides ${n.p('key_count',s.key_count)} keys, including ${n.p('function_keys',s.function_keys)}, a numeric keypad and separate cursor keys. Its navigation section contains ${n.p('navigation_keys',s.navigation_section)}. Key assignments and editing conventions follow ${n.ref('keyboard_standard_id',s.keyboard_standard_id,'Shared keyboard command and assignment standard')}.`);return;}
 if(id==='device.aurelia_ram_16kb_card'){n.c('Expansion and address mapping',`The card adds ${n.p('capacity_kb',t.capacity_kb)} KiB to ${n.refs(t.compatible_with,'Computer expanded by this card','host_')}, raising lower RAM from 44 to 60 KiB before workspace reservations. Eight ${n.ref('dram_id',t.physical_population.chip_id,'DRAM used on the expansion card')} chips form an 8-bit bank. Its four 4 KiB pages occupy B000–EFFF in the normal mapping; the existing common system RAM remains at F000–FFFF.`,`The card occupies one expansion slot. Install it with power off and restart: firmware discovers, tests and maps the pages without address switches. Common-memory service routines save the mapping, temporarily select ROM or video RAM and restore the card pages on return. The host must refresh the card even while it is overlaid; the exact refresh interface remains to be qualified.`);return;}
 if(id==='device.flexiprint40'){n.c('Printing mechanism and connection',`FlexiPrint40 combines ${n.ref('print_mechanism_id',s.mechanism_id,'Printing mechanism fitted to this printer')} with ${n.ref('bus_controller_id',s.controller_id,'FlexiBUS device-side interface controller')} to receive print data over FlexiBUS.`);return;}
 if(id==='device.flexidisk'||id==='device.flexidisk_ii'){n.c('Removable storage and host access',`This external drive uses ${n.p('media',s.media)} media and connects over ${n.p('connection',s.connection)}. ${s.controller_id?`Its bus interface is implemented by ${n.ref('bus_controller_id',s.controller_id,'FlexiBUS device-side controller in the drive')}.`:`It handles ${n.p('disk_formats',s.disk_formats)} disk formats and is usable from ${n.p('supported_hosts',s.usable_from)}.`}`);return;}
 if(id==='device.apple2_expansion_card'){n.c('Apple II peripheral expansion',`The card adds ${n.p('flexibus_ports',s.flexibus_ports)} FlexiBUS ports and a Disk II-compatible controller interface to Apple II. Native 6502 drivers and examples operate both interfaces; the card supplies neither a Z80 execution environment nor a CP/M port.`);return;}
 if(id==='device.artemis_cpm80_module'){n.c('CP/M guest execution',`This expansion module lets ${n.refs(t.compatible_with,'Host of the separate CP/M guest environment','host_')} run qualified Aurelia/CP/M binaries on a ${n.ref('guest_cpu_id',s.cpu_id,'Processor executing guest Z80 instructions')} with ${n.p('guest_ram_kib',s.local_ram_kb)} KiB of local RAM. The ${n.ref('peripheral_bridge_id',s.bridge_design_id,'Virtual peripheral interface between guest and host')} mediates device access.`,`This is a separate guest execution path, not native execution by ERA or recompilation to it. Capability queries must describe the emulated CP/M environment and must not expose ERA facilities that the guest cannot use.`);return;}
 if(id==='device.s100_flexibus_card'){n.c('S-100 bus and peripheral service',`The configurable 8-bit S-100 interface provides ${n.p('flexibus_ports',s.flexibus_ports)} ports using ${n.ref('host_controller_id',s.controller_id,'Host-side bus controller')} and the ${n.ref('bus_protocol_id',s.transport_id,'Peripheral transport implemented by the card')} protocol. Controller die count remains unspecified. Address decode, waits, power and conflicts require qualification on named hosts.`,`CP/M BIOS adapters, installation diagnostics and optional Platform Extensions/TUI support target qualified 8080/Z80 systems with declared ISA and memory prerequisites. Driver loading from an existing boot disk is the baseline; booting through FlexiBUS needs a separately qualified boot ROM. The card does not include a Disk II interface.`);return;}
 if(id==='device.apple2_video_card'||id==='device.s100_video_card'){n.c('Host integration',`${s.host==='Apple II'?'This Apple II card uses slot decoding and a driver ROM while preserving the native memory map and avoiding conflicts with other cards. Native 6502 drivers, callable libraries and examples expose a card API; existing graphics are not transparently redirected, and no CP/M port or Z80 CPU is supplied.':'This card uses a configurable 8-bit S-100 interface. Named hosts require address-decode, wait-state, power and conflict qualification. CP/M BIOS adapters, diagnostics and optional Platform Extensions/TUI support are provided for qualified 8080/Z80 hosts with declared ISA and memory prerequisites.'}`);n.c('Independent display and sprite memory',`The card reuses ${n.ref('display_controller_id',s.display_controller_id,'Aurelia graphics controller reused on this host')} with ${n.p('video_ram_kib',s.video_ram_kb)} KiB of local display RAM from ${n.p('video_chip_count',s.video_ram_chip_count)} ${n.ref('video_chip_id',s.video_ram_chip_id,'Display DRAM')} chips. Windowed or addressed host access leaves display refresh independent and does not add general-purpose host RAM. Two ${n.ref('sprite_chip_id',s.sprite_memory.chip_id,'SRAM dedicated to sprites')} chips provide an exclusive 1 KiB, 8-bit sprite bus.`,`All five sprites remain available in supported Aurelia-family modes through a host-specific upload interface. The card has no Aurelia system DMA controller. Output uses ${n.ref('video_link_id',s.video_link_id,'Digital monitor connection')}; 80-column output requires a compatible 640-pixel monitor, and all modes need card/monitor qualification. Host CPU performance limits drawing throughput. No monitor or FlexiBUS ports are included.`);return;}
 if(id==='device.logix_mouse'){n.c('Pointing and scrolling controls',`This relative X/Y mouse uses ${n.ref('bus_id',s.interface_id,'Peripheral transport for the mouse')} and ${n.ref('pointing_protocol_id',s.class_protocol_id,'Pointing-device reports and control protocol')}. It has ${n.p('buttons',s.buttons)} primary/secondary buttons and two independent rollers: one beneath the middle finger for vertical scrolling, and a thumb-side roller for horizontal scrolling. Mechanical-ball quadrature tracking is the design baseline.`,`It supports ${n.refs(t.compatible_computers,'Computer supporting the pointing-device interface','host_')}. Resolution, tracking, accidental actuation, handedness, detent force, reach and side-wheel placement require qualification. Port power is a target; current draw, connector and protection remain to be validated.`);return;}
 if(id==='device.artemis_professional_video_128kb'){professional(n,t);return;}
 if(id==='device.mono_pro_17'){n.c('Professional grayscale display',`The ${n.p('diagonal_inches',s.diagonal_inches)}-inch display uses ${n.ref('controller_id',s.controller_id,'Pixel-index and grayscale palette controller')} to present a fixed 800 × 600 progressive raster. Its ${n.p('intensity_levels',s.grayscale_levels)} intensity levels support four simultaneous shades in 800 × 600 × 2bpp and sixteen in 640 × 200 × 4bpp. A 4-bit intensity DAC drives a level-matched linear amplifier; TTL/ECL-only video input is insufficient.`,`The RGB palette command format remains 12-bit: equal-channel codes 000 through FFF select corresponding grayscale levels. Other RGB values need a documented luminance mapping, with DAC/gamma calibration on the actual CRT.`);n.c('Timing target and OEM qualification',`The production target is ${n.p('refresh_hz',s.timing_target.refresh_hz)} Hz at totals of ${n.p('raster_totals','1024 pixels × 625 lines')}, requiring ${n.p('horizontal_khz',s.timing_target.horizontal_khz)} kHz horizontal and ${n.p('pixel_clock_mhz',s.timing_target.pixel_clock_mhz)} MHz pixel timing.`,`A Ball HD-series HD17H horizontal-format OEM assembly with the analog/linear-video option is a candidate, not a confirmed or qualified supplier. Its documented 26–36 kHz horizontal and 40–80 Hz vertical ranges and typical 35 MHz linear amplifier do not establish the target timing or grayscale performance. Qualify a deflection revision, contrast, grayscale settling, geometry and corner focus. The 56 Hz/35 kHz fallback remains an engineering option rather than the production specification.`);return;}
 if(id.startsWith('device.rom_cartridge.')){n.c('ROM cartridge and host fit',`${n.r.name} is a physical ROM cartridge, with its program content supplied by the software edition in its BOM.${t.compatible_with?' It is intended for '+n.refs(t.compatible_with,'Compatible host for this physical cartridge','host_')+'.':''}`);return;}
 if(n.r.kind==='storage_device'||t.connection==='internal_storage'){n.c('Storage mechanism',s.capacity_mb?`The internal hard disk provides ${n.p('capacity_mb',s.capacity_mb)} MB${s.interface?' through a '+n.p('interface',s.interface):''}.`:`This internal ${n.p('diameter_inches',s.size_inch)}-inch floppy mechanism uses ${n.p('density',s.density)} recording.${s.sides?' It is double-sided (DS/DD); formatted capacity remains unspecified.':''}`);return;}
 if(id.endsWith('.base_memory')){n.c('System memory organization',`The subsystem provides ${n.p('capacity_kb',s.capacity_kb)} KiB in ${n.p('bank_count',s.physical_population.bank_count)} ${n.p('bank_width_bits',s.physical_population.bank_data_width_bits)}-bit bank${s.physical_population.bank_count===1?'':'s'}, including common system RAM. No parity is fitted, and display memory is separate. Physical bank/page decoding must preserve the existing mapper and common-memory reservations.`);return;}
 if(id.endsWith('.video')){n.c('Display subsystem',`The subsystem implements ${n.ref('video_profile_id',t.specification_id,'Functional video profile')} using ${n.ref('controller_id',s.controller_id,'Video controller in the subsystem')}. Display RAM has an 8-bit bus independent of system RAM. Sprite memory uses a separate 8-bit bus, independent of both system and display RAM.`);return;}
 if(id.endsWith('.system_rom')){n.c('Executable system cartridge',`This replaceable cartridge supplies ${n.p('capacity_bytes',s.capacity_bytes)} bytes of directly executable, shared read-only AIONix2 code for ${n.refs(t.compatible_with,'Host for the system cartridge','host_')}. Private writable state and patch overlays remain in DRAM. The ROM organization, carrier, connector, enclosure and access timing require host qualification.`);return;}
 throw Error('No device narrative for '+id);
}
function professional(n,t){const s=t.specification;n.c('Professional display engine',`The card implements ${n.ref('graphics_design_id',s.technology_id,'Professional graphics architecture')} with ${n.ref('controller_id',s.controller_id,'Professional graphics controller')} for ${n.refs(t.compatible_with,'Host for the additional professional display card','host_')}. It uses one general 32-bit slot alongside the primary card in the dedicated video slot, with independent display handles, palettes, clocks, DMA/address resources and input focus.`,`${n.ref('monitor_id',s.monitor_id,'Qualified fixed-raster display intended for the professional card')} uses a fixed 800 × 600 raster. The card retains the text/bitmap capabilities of ${n.ref('legacy_card_id',s.legacy_card_id,'Source of the inherited display modes')}; older logical modes are centered without scaling. Older full-screen timings require an explicitly compatible monitor profile, with logical/output coordinate mapping reported to software.`);
n.c('Memory, drawing and redraw',`The framebuffer/list allocation contains ${n.p('video_ram_bytes',s.video_ram_bytes)} bytes. Five legacy sprites use a separate ${n.p('sprite_sram_bytes',s.separate_sprite_sram_bytes)}-byte SRAM bank built from two AION 2114 chips; 800 × 600 coordinate and line-budget validation remains required, and no sixth pointer sprite is implied.`,`Drawing supports overlap-safe clipped rectangle copies, fills, masked Boolean raster operations and all-octant integer lines. Lookup-table antialiasing with four output shades is optional at 800 × 600. Retain vector geometry and redraw dirty areas or exposed pan strips. XOR suits temporary simple cursors, not removal of overlapping antialiased geometry. A full 800 × 600 × 2bpp double buffer does not fit.`);
n.c('Palette sequencing and qualification',`Reserve ${n.p('palette_list_bytes',1536)} bytes at ${n.p('palette_list_address_range','0x1FA00–0x1FFFF')} for up to ${n.p('palette_command_count',512)} three-byte commands. Byte 0 is an unsigned scanline delta; byte 1 combines palette-register index and red, and byte 2 combines green and blue, each colour component occupying four bits. The palette has sixteen registers.`,`Deltas accumulate from active output line zero; zero permits another write at the same boundary. Execute in preceding horizontal blank and latch before the line. A 10-bit count distinguishes 0–512 entries. Split gaps over 255 lines with harmless writes, which still consume entries. At vertical blank restore the initial palette and list position; edit or swap only in a defined safe interval.`,`The target is at most four writes per output-line boundary, subject to transfer/settling qualification at the faster raster. Reject over-budget lists. Static grayscale is the CAD default; 512 commands neither imply 512 distinct scanlines nor sixteen simultaneous shades in a 2bpp mode.`);}
function computer(n,t){
 const id=n.r.id,aurelia=id.includes('aurelia'),athena=id.includes('athena'),s=t.technical_profile;
 n.c('System architecture',`${n.r.name} is a ${t.form_factor} built around ${n.ref('processor_id',t.processor.part_id,'Processor fitted to this computer')}.${t.role?' The PRO configuration serves as a network server.':''}`,athena?'Its EEPROM BIOS boots and initializes hardware, runs diagnostics and selects ROM-based AIONix2/recovery or disk patches. BIOS capacity and chassis mechanics remain unspecified. External application ROM cards are not supported.':`The ${n.p('expansion_bus_bits',t.io_and_expansion.expansion_slots.width_bits)}-bit expansion interface supports Plug and Execute.${aurelia?' Connector space is reserved for a future 32-bit interface; that is not current bus width.':' The rear ROM/EEPROM position serves the operating system and the front position serves office/application software. A replaceable, non-hot-swappable video card uses a dedicated keyed connector without consuming a general-purpose slot; buffered data/address, wait/ready and DMA access are provided, but electrical pinout remains open.'}`);
 if(aurelia){const m=s.memory,o=m.organization;const expanded=m.expanded_organization;
 n.c('System RAM and bank switching',`The ${n.ref('memory_model_id',t.memory_interface.organization_id,'Aurelia logical memory and bank-switching contract')} maps ${n.p('lower_ram_kib',o.contiguous_lower_ram_kb)} KiB of lower RAM plus ${n.p('common_ram_kib',o.common_system_ram_kb)} KiB of fixed common RAM at F000–FFFF. ${expanded?`The normal 48 KiB view maps RAM at 0000–AFFF and ROM/cartridge/video windows at B000–EFFF. ${n.ref('expansion_card_id',t.memory_interface.expansion_id,'Card that fills the normal upper window with RAM')} extends lower RAM to 60 KiB by supplying B000–EFFF, reaching the 64 KiB system limit.`:'The 64 KiB normal view maps lower RAM at 0000–EFFF.'} Within 7000–EFFF, 4 KiB pages may temporarily expose ROM or video RAM; hidden RAM retains its contents and is restored after service calls.`,`The ${n.ref('system_controller_id',t.memory_interface.system_controller_id,'Controller responsible for system DRAM refresh, mapping and DMA')} refreshes every installed bank independently of CPU activity and latches physical DMA bank selections so mapping changes cannot redirect a transfer. The base population uses ${n.p('ram_bank_count',m.physical_population.bank_count)} 8-bit bank${m.physical_population.bank_count===1?'':'s'}, with common RAM included and no parity. Mixed module types are not allowed.`);
 n.c('Firmware and built-in video',`Motherboard ROM contains ${n.p('firmware_services',t.firmware_contents)}. The ${n.ref('video_controller_id',s.video.controller_id,'Built-in video controller')} operates display RAM on an independent 8-bit bus; sprite RAM has a further separate 8-bit bus.`,`${n.ref('recommended_system_id',t.recommended_software_id,'Recommended operating-system implementation')} supplies the native Z80/CP/M environment. Applications use ${n.ref('application_api_id',s.software_compatibility.api_id,'Portable application interface implemented on this host')} and query usable dimensions rather than branching on model names. Native 40 × 25 and 80 × 25 text are available subject to monitor capabilities.`);
 }else{const m=s.memory;
 n.c('RAM population and software environment',`Two matched 32-bit modules form each capacity bank, selected independently on the shared bus. Fill banks in order; decode and refresh every rank. Replace the population when changing density rather than mixing module types. Cross-host connector and timing qualification remains open. ${athena?'Maximum motherboard RAM and socket count remain unspecified and are distinct from the CPU address-space limit.':`The system RAM limit is ${n.p('maximum_ram_kib',t.memory_constraints.max_ram_kib)} KiB. No parity or ECC is fitted; adding it requires a separately qualified BOM.`}`,t.integration_requirements?.sourcing_policy||'',athena?`A replaceable cartridge supplies ${n.p('system_rom_bytes',m.os_rom.capacity_bytes)} bytes of shared executable AIONix2 code; private writable state and patch overlays consume DRAM. Cartridge chip organization, connector, timing and exchange procedure require qualification. ${n.ref('recommended_system_id',t.recommended_software_id,'Operating-system implementation for this host')} preserves documented ERA/AIONix binaries through versioned compatibility, with individual editions still requiring qualification.`:`Native ERA/AIONix applications use ${n.ref('application_api_id',s.software_compatibility.api_id,'Portable application interface on this host')}. They discover usable display dimensions and the native 40 × 25 / 80-column modes through capability queries.`);
 graphics(n,s.video);
 if(t.integration_requirements?.video_ram_policy)n.chapters.find(c=>c.chapter_name==='Display memory and sprites').description+='\n\n'+t.integration_requirements.video_ram_policy;
 if(s.networking){const x=s.networking;n.c('Network service',`One removable NIC occupies one of the four general-purpose slots, providing server operation over ${n.ref('network_stack_id',x.technology_ids[0],'Network stack used by the server')} and ${n.ref('network_link_id',x.technology_ids[1],'Shared-rate link and negotiation protocol')}. Firmware permits ${n.p('supported_network_rates_kbps',x.supported_rates_kbps)} kbit/s, with the highest listed rate as its ceiling. The actual common rate also depends on every admitted station and qualified link.`);}
 }
 n.chapters[0].description+='\n\n'+`Installed RAM must satisfy the selected configuration, and a monitor must connect to a fitted video provider. ${athena?'The internal system cartridge does not establish support for external application cartridges.':'Cartridges must match both the software platform and their socket role; external application cartridges are supported.'}`;
}
function basePart(n,t){const s=t.specification||{},id=n.r.id;
 if(['base_part.z80a','base_part.z80b'].includes(id)){n.c('Processor role',`${n.r.name} is a Z80 processor specified for ${n.p('clock_mhz',s.clock_mhz)} MHz operation${s.data_width_bits?` with an ${n.p('data_width_bits',s.data_width_bits)}-bit data interface`:''}.`);return;}
 if(id==='base_part.flexibus_host_controller'||id==='base_part.flexibus_device_controller'){n.c('Bus-controller role',`This chip implements the ${id.includes('host')?'computer-side host':'peripheral-side device'} interface for ${n.ref('interface_id',t.specification_id,'Bus protocol implemented by this controller')}.`);return;}
 if(id==='base_part.artemis_mmu'){n.c('Memory-management role',`The MMU implements ${n.ref('memory_architecture_id',t.specification_id,'Address translation and protection architecture implemented by this part')} for Artemis system memory.`);return;}
 if(s.capacity_kbit){memoryChip(n,s);return;}
 if(id==='base_part.artemis_graphics_chip'){graphics(n,s,'chip');return;}
 if(id==='base_part.aurelia_video_chip'){aureliaChip(n,s);return;}
 if(id==='base_part.artemis_graphics_chip_64kb'){n.c('Graphics-controller extension',`This revision extends ${n.ref('base_controller_id',s.base_controller_id,'Earlier controller whose rendering and sprite architecture is retained')} for ${n.ref('card_id',s.card_id,'Board carrying the detailed qualified memory layout')}. It adds 64 KiB display addressing, 640 × 400 × 2bpp and 640 × 200 × 4bpp modes, and bounded prefetch/sequencing for ${n.ref('palette_list_id',s.palette_list_id,'Horizontal-retrace palette update protocol')}. Earlier modes, five sprites with independent SRAM, refresh and bounded host/DMA arbitration remain part of the design.`);pixelPipeline(n,s);return;}
 if(id==='base_part.aurelia_system_controller'){systemController(n,s);return;}
 if(id==='base_part.artemis_fdd_hdd_controller'){n.c('Storage control',`The controller supports ${n.p('floppy_count',s.supported_fdd_count)} ${n.p('floppy_size_inches',s.fdd_size_inch)}-inch double-density floppy drives and a hard-disk interface. Hard-disk interface support does not mean an HDD is bundled with standard Artemis.`);return;}
 if(id==='base_part.sony_kv1204_display_assembly'){n.c('OEM display assembly',`The supplied display assembly reuses the ${n.p('included_elements',s.reused_elements)}. These are the OEM supply boundary; other monitor electronics remain separate parts.`);return;}
 if(id==='base_part.brimar_m36_141w_crt'){n.c('Display tube and supply boundary',`This ${n.p('diagonal_inches',s.diagonal_inch)}-inch ${n.p('manufacturer',s.manufacturer)} ${n.p('model',s.model)} is supplied as a bare CRT. The yoke, high-voltage and deflection electronics, power supply and video amplifier are separate purchases.`);return;}
 if(id==='base_part.nec_pc8853_display_assembly'){n.c('OEM assembly and required adaptation',`The ${n.p('diagonal_inches',s.diagonal_inches)}-inch assembly has a ${n.p('dot_pitch_mm',s.dot_pitch_mm)} mm dot pitch. Its historical 640 × 400 raster used 24.83 kHz horizontal and 56.4/55.4 Hz vertical timing with a stock digital RGB input.`,`The Logix design requires a qualified 26.88 kHz/60 Hz progressive adaptation of the OEM tube/yoke/deflection assembly, plus AION palette/DAC electronics. The stock monitor is not plug-compatible; historical shipment establishes neither an OEM supply agreement nor modified-timing qualification.`);return;}
 if(id==='base_part.aurelia_monitor_dac'){n.c('Monochrome pixel conversion',`The converter maps a ${n.p('input_bits',s.input_bits)}-bit digital pixel index to ${n.p('intensity_levels',s.beam_voltage_levels)} beam-intensity levels.`);return;}
 if(id==='base_part.color_monitor_controller'||id==='base_part.mono_monitor2_controller'){n.c('Programmable monitor palette',`The controller provides ${n.p('palette_registers',s.palette_registers)} palette registers. ${s.register_width_bits?`Each stores a ${n.p('palette_precision_bits',s.register_width_bits)}-bit RGB value.`:'Each stores an 8-bit grayscale intensity.'}`);return;}
 if(id==='base_part.mono_pro_controller'){n.c('Pixel-to-intensity conversion',`A ${n.p('input_bits',s.input_bits)}-bit input selects one of ${n.p('palette_entries',s.palette_entries)} ${n.p('palette_entry_bits',s.palette_entry_bits)}-bit palette entries at a ${n.p('pixel_clock_mhz',s.pixel_clock_mhz)} MHz pixel clock. The chip supplies DAC switching outputs to an external precision resistor ladder and wideband amplifier; high-voltage, deflection and power-supply circuits remain separate. The planning die area is ${n.p('die_area_mm2',s.die_area_planning_mm2)} mm².`);return;}
 if(id==='base_part.color_pro_monitor_controller'){n.c('Colour conversion and line updates',`A 4-bit pixel index selects one of ${n.p('palette_registers',s.palette_registers)} ${n.p('palette_entry_bits',s.register_width_bits)}-bit RGB entries. Three 4-bit DAC channels feed external voltage amplifiers; DAC ladders, analog drivers and high-voltage/deflection electronics are explicit board components, not assumed on-chip functions. ${n.ref('palette_list_id',s.palette_list_id,'Line-boundary palette update protocol')} controls palette changes.`,`The RGB amplifier design target is 25–30 MHz. DAC settling, text focus, convergence and line-boundary commits require qualification.`);return;}
 if(id==='base_part.professional_graphics_controller'){n.c('Professional graphics implementation',`The controller implements ${n.ref('graphics_architecture_id',s.technology_id,'Professional drawing and display architecture')} with ${n.p('addressable_memory_bytes',s.memory_addressing_bytes)} bytes of memory addressing. Engineering prototypes may use discrete or microcoded logic. Production custom silicon, timing and arbitration must be qualified before release; no performance or process-node qualification is implied.`);return;}
 if(id==='base_part.mono_pro_17_controller'){n.c('Professional grayscale conversion',`Four pixel codes select four programmable values from a ${n.p('intensity_levels',s.grayscale_levels)}-level range. The custom controller drives a 4-bit DAC and a qualified linear video amplifier; CRT deflection and high-voltage electronics remain separate. Qualify pixel-clock settling, distinct grayscale levels, geometry, corner focus, phosphor persistence and sync compatibility.`);return;}
 if(t.specification_id&&id.startsWith('base_part.era')){const m=t.manufacturing_planning;n.c('Processor and fabrication target',`The processor implements ${n.ref('architecture_id',t.specification_id,'Instruction-set and processor architecture')} at ${n.p('clock_mhz',s.clock_mhz)} MHz. ${id.includes('erav1')?`It remains on the original ${n.p('process_um',m.node_um)} µm Micralign process with a ${n.p('die_area_mm2',m.die_area_mm2)} mm² planning die; speed-bin and electrical qualification are unchanged.`:`AION Labs is the initial manufacturer. The design targets a ${n.p('process_um',m.node_um)} µm process on ${n.p('wafer_diameter_mm',m.wafer_diameter_mm)} mm wafers, a ${n.p('die_area_mm2',m.die_area_mm2_target)} mm² die and a ${n.p('transistor_budget',m.transistor_budget_target)}-transistor budget.`}`);return;}
 if(s.capacity_mb){n.c('Storage capacity',`This hard-disk mechanism supplies ${n.p('capacity_mb',s.capacity_mb)} MB of storage.`);return;}
 if(s.capacity_bytes){n.c('System ROM storage',`This physical ROM provision stores ${n.p('capacity_bytes',s.capacity_bytes)} bytes of system code for its owning Athena cartridge. Execution behaviour belongs to the software and cartridge definitions.`);return;}
 if('capacity_kb' in s){n.c('Boot firmware storage',`This part provides boot/diagnostic firmware storage for ${n.r.id.includes('athena_server')?'Athena Server':'Athena'}. Capacity remains unspecified.`);return;}
 if(!Object.keys(s).length){n.c('Component role',n.r.description);return;}
 throw Error('No base-part narrative for '+id);
}
function memoryChip(n,s){const id=n.r.id,dram=!id.includes('2114');
 n.c('Memory organization',`This ${dram?'dynamic':'static'} RAM provides ${n.p('capacity_kbit',s.capacity_kbit)} Kibit organized as ${n.p('organization_words',s.organization_words)} words with a ${n.p('data_width_bits',s.data_width_bits)}-bit data interface. ${s.base_product_id?`It is the ${n.p('process_um',s.node_um)} µm ${n.p('recipe',s.manufacturing_recipe)} revision of ${n.ref('base_part_id',s.base_product_id,'Earlier part whose capacity is preserved')}, not a 128- or 256-Kibit device.`:''}`);
 if(id==='base_part.aion_4116')n.c('Access, refresh and electrical targets',`A single random read/write port accesses a ${n.p('array_geometry',`${s.array_rows} × ${s.array_columns}`)} array; there is no serial shift register. Random-cycle time targets ${n.p('random_cycle_target_ns',s.random_cycle_target_ns)} ns. The controller must refresh all rows, including hidden pages; retention, scheduling and speed grade require silicon qualification.`,`Supply rails are ${n.p('supply_rails_v',s.supply_rails_v)} V. A 16-pin DIP is the target package; the qualified ordering code remains open.`);
 else if(id==='base_part.aion_2114')n.c('Asynchronous access and electrical targets',`The SRAM needs no refresh and targets a ${n.p('random_cycle_target_ns',s.random_cycle_target_ns)} ns random cycle from a ${n.p('supply_rails_v',s.supply_rails_v)} V supply. The package target is an 18-pin DIP, subject to electrical qualification.`);
 else if(s.speed_qualification_targets){const x=s.speed_qualification_targets;n.c('Speed and electrical qualification',`Preferred targets are ${n.p('preferred_access_ns',x.preferred_row_access_ns)} ns row access and ${n.p('preferred_cycle_ns',x.preferred_random_cycle_ns)} ns random cycle. The fallback is ${n.p('fallback_access_ns',x.fallback_row_access_ns)} ns access with a ${n.p('fallback_cycle_range_ns',x.fallback_random_cycle_ns_range.join('–'))} ns cycle. The ${n.p('stretch_access_ns',x.stretch_row_access_ns)} ns stretch target is not the launch baseline; actual access time is unknown until qualification.`,`Package, supply rails, speed, loading, page timing, temperature, retention, refresh and yield need independent qualification.`);}
 else n.chapters[0].description+=' '+(s.electrical_contract?'Package, supply rails, pinout, timing, retention and refresh remain release gates. A common module interface requires all-bank qualification; this definition does not change capacity or bus width.':'Package and supply rails remain unspecified.');
 const m=s.manufacturing_planning;
 if(m?.recipe_variants){n.c('Fabrication alternatives',`Two 3 µm routes are compared on ${n.p('wafer_mm',m.wafer_mm)} mm wafers. The baseline ${n.ref('control_recipe_id',m.recipe_variants[0].manufacturing_capability_id,'Control fabrication recipe')} uses a ${n.p('control_die_mm2',45)} mm² die, defect density ${n.p('control_defects_cm2',2)} cm⁻² and processed-wafer estimate ${n.p('control_wafer_cost_usd',235)} USD; ${n.ref('repair_recipe_id',m.recipe_variants[1].manufacturing_capability_id,'Repair-enabled fabrication recipe')} uses ${n.p('repair_die_mm2',47.25)} mm², ${n.p('repair_defects_cm2',1.7)} cm⁻² and ${n.p('repair_wafer_cost_usd',255)} USD. These are manufacturing estimates.`,`Evaluate 2.75 µm against repaired 3 µm only if it reduces cost; later 2/1.5 µm releases are prospective.`);}
 else if(m)n.c('Silicon planning',`Estimated die area is ${n.p('die_area_range_mm2',m.die_area_mm2_range.join('–'))} mm², with ${n.p('central_die_area_mm2',m.die_area_mm2_central)} mm² as the central planning value.`);
 else if(s.die_area_mm2)n.c('Silicon planning',`The revised die-area target is ${n.p('die_area_mm2',s.die_area_mm2)} mm².`);
}
function aureliaChip(n,s){const d=s.implementation_design,m=d.manufacturing_planning;
 n.c('Rendering and external memory',`This dedicated graphics ASIC produces ${n.p('pixel_bits',s.digital_output_bits)}-bit pixel indices. It performs fetch/address generation, eight-pixel glyph expansion, colour selection and fixed-priority sprite composition; it is not a general-purpose CPU. A separately clock-enabled raster sequencer consumes completed pixels and generates sync.`,`External display RAM is ${n.p('display_ram_kib',s.video_ram_kb)} KiB from ${n.p('display_chip_count',s.video_ram_chip_count)} ${n.ref('display_chip_id',s.video_ram_chip_id,'DRAM used by the controller’s display-memory interface')} chips. Two ${n.ref('sprite_chip_id',s.sprite_memory.chip_id,'SRAM chips on the independent sprite bus')} devices form a separate 1 KiB, 8-bit sprite bank. Auto-increment uploads arbitrate against sprite reads; descriptor-bank selection latches at vertical blank. Display reads and full-array refresh impose bounded host/DMA backpressure.`);
 n.c('On-chip buffering and scanout',`The on-chip storage budget is ${n.p('internal_storage_bytes',d.internal_buffers.total_storage_bytes)} bytes, included in die estimates: two 160-byte character/attribute row caches, 40-byte sprite shifters, 40-byte sprite staging and a four-bank, 160-byte pixel FIFO. Each 40-byte FIFO bank holds 4-bit pixels and moves through ${n.p('fifo_states',['free','filling','ready','reading'])}; publish complete banks only, backpressure a full queue and prefill before active display. Underrun emits border colour, maintains sync and records diagnostic status.`,`The text engine caches eighty character codes and attributes and prefetches the next row over eight glyph scanlines. It expands each glyph byte into eight pixels, fetches sprite rows and applies priority before publishing. Repeated bitmap lines are fetched again: the FIFO is neither an extra framebuffer nor a guaranteed retained scanline.`);
 n.c('Timing targets and validation',`The master and high-resolution pixel clock target ${n.p('master_clock_mhz',d.clock_targets.master_mhz)} MHz; low-resolution scanout targets ${n.p('low_resolution_clock_mhz',d.clock_targets.low_resolution_pixel_mhz)} MHz. The maximum FIFO output target is ${n.p('fifo_output_mbytes_s',d.clock_targets.maximum_pixel_fifo_output_mbytes_per_second)} Mbytes/s. Only short scanout/counter paths operate at dot rate; renderer work uses block expansion and clock enables.`,`At the 375 ns DRAM-cycle target, eighty glyph reads plus twenty amortized next-row bytes give one hundred display reads and 37.5 µs per scanline on average. Forty sprite bytes take 10 µs on their independent bus at a 250 ns SRAM cycle. The full FIFO holds 320 pixels and drains in 22.349 µs at high resolution; two ready pages allow 11.175 µs. Row transitions, descriptors, refresh, repeated bitmap lines and uploads still require deadline analysis and process-corner qualification; these averages are not a timing proof.`);
 n.c('Fabrication and integration boundary',`The manufacturing plan uses 3–3.5 µm NMOS, process-matched laser-written masks from the secret facility and AION Labs wafer fabrication. Estimated transistor count is ${n.p('transistor_range',m.transistors_range.join('–'))}, with ${n.p('central_transistor_count',m.transistors_central)} as the central value. At 3 µm, die area is estimated at ${n.p('die_area_3um_range_mm2',m.die_area_mm2_at_3um_range.join('–'))} mm², central ${n.p('die_area_3um_central_mm2',m.die_area_mm2_central_at_3um)}; at 3.5 µm it is ${n.p('die_area_3_5um_range_mm2',m.die_area_mm2_at_3_5um_range.join('–'))} mm², central ${n.p('die_area_3_5um_central_mm2',m.die_area_mm2_central_at_3_5um)}.`,`Display DRAM, sprite SRAM, cable drivers/transceivers and monitor palette/DAC circuitry remain external. The larger sprite-interface package and PCB allowance belongs to assembly cost, not additional on-chip storage.`);
}
function systemController(n,s){n.c('Host mapping and memory refresh',`This controller serves ${n.p('host_clocks_mhz',s.host_clock_mhz)} MHz Aurelia hosts with a ${n.p('address_bits',s.cpu_address_bits)}-bit CPU address interface and an ${n.p('data_bits',s.data_width_bits)}-bit data bus. The map fixes lower RAM at 0000–6FFF, switches 4 KiB pages in 7000–EFFF and preserves common RAM at F000–FFFF; boot ROM appears at zero until normal-map release.`,`An always-running refresh timer, row counter and arbiter operate during execution, HALT and DMA. Initialize them before using RAM and qualify row count/retention against the installed chips. Supported system populations are ${n.p('supported_populations',s.refresh.supported_populations)}. Hidden pages and expansion RAM are included; display RAM is refreshed by the video controller, while sprite SRAM needs none.`);
 n.c('Bounded DMA transfers',`The controller has ${n.p('dma_contexts',s.dma.transfer_contexts)} transfer contexts and ${n.p('dma_engines',s.dma.active_transfer_engines)} active engine, with 16-bit destination addresses and lengths. Supported operations are ${n.p('dma_operations',s.dma.operations)} with ${n.p('address_steps',s.dma.address_steps)} addressing. Physical source/destination banks and offsets latch at start; split logical buffers at page boundaries, and reject ROM writes, unmapped banks and invalid lengths.`,`Bounded bursts preserve CPU and refresh service and honour device-ready/WAIT handshakes; video uploads yield to display deadlines. Completion/error interrupts, a readable remaining count and controlled abort expose transfer state; reset disables DMA. Display and sprite uploads use auto-increment ports with backpressure. Disk/FlexiBUS DMA needs qualified request/ready or FIFO endpoints and drivers, while programmed I/O remains supported. Numeric grant limits need cycle-level validation.`);
 n.c('Silicon planning',`The estimated die-area range is ${n.p('die_area_range_mm2',s.manufacturing_planning.die_area_mm2_range.join('–'))} mm², with a ${n.p('central_die_mm2',s.manufacturing_planning.die_area_mm2_central)} mm² central value and a ${n.p('package_allowance_usd',s.manufacturing_planning.package_allowance_usd)} USD manufacturing package allowance.`);}
// Shared software contracts are expressed once per edition; host and dependency
// references keep semantic keys and roles, never numeric list-position keys.
function runtime(n,t){
 const platform=t.execution_target==='z80_cpm'?'Z80/CP/M':'native ERA/AIONix',hosts=t.platform_support.map(x=>x.computer_id),d=t.distribution,m=t.minimum_resources;
 const role={operating_system:'operating system',network_extension:'network extension',application:'application suite',client:'client',server:'server',team_server:'development-team server',development_client:'development client',development_tools:'development toolset'}[t.role];
 let body=`This ${role} targets ${platform}${hosts.length?' on '+n.refs(hosts,'Supported execution host for this edition','host_'):'. No specific host configuration is listed'}.`;
 if(m.installed_ram_kb!==null)body+=` The recorded installed-RAM requirement is ${n.p('minimum_ram_kib',m.installed_ram_kb)} KiB.`;
 if(t.dependency_ids.length)body+=` It requires ${n.refs(t.dependency_ids,'Runtime prerequisite for this software edition','runtime_')}.`;
 if(d.medium==='diskette')body+=` ${d.installation==='server_hdd'?'Install the server from diskette onto its HDD.':d.installation==='client_startup_diskette'?'A local startup diskette boots the client under its existing networking OS before bounded transfers load further modules or data.':'The edition is delivered on diskette.'}`;
 else if(d.medium==='cartridge')body+=' The software image is supplied in its matching physical ROM cartridge; hardware construction belongs to that cartridge.';
 else body+=' The external supplier’s delivery medium is unspecified.';
 if(d.disk_format)body+=` Media use ${n.p('disk_format',d.disk_format)} format through ${d.channel}.`;
 if(d.fulfillment==='included_in_package')body+=' This edition is supplied as part of its containing package.';
 body+=' Application workspace and ROM footprint remain unspecified'+(m.rom_bytes!==null?' beyond the explicit system-ROM requirement.':'.');
 n.c('Execution and delivery',body);
}
function portability(n,t){if(!t.portability_contract)return;
 n.c('Portable implementation',`The implementation uses ${n.ref('portable_api_id',t.portability_contract.api_id,'Shared C service contract used by this edition')}. Keep application/document algorithms separate from platform adapters; query display dimensions and attributes, use semantic colours and clipping, and handle allocation failures with bounded buffers and banked-object handles. Persistent records are explicitly encoded and versioned rather than raw structures or pointers. Recompile and adapt OS-specific modules for another target, then test its resource limits; source portability does not extend the list of qualified hosts.`);}
function pulseFiles(n,t){n.c('Document ownership and safe updates',`Standalone Pulse reads, edits and writes supported closed Abacus files with exclusive writer ownership. It checks format versions and supported features before writing and rejects unsupported edits without dropping data. Save through a validated replacement file with recoverable replacement of the previous version. Preserve formula text/encoding and invalidate changed cached results; Abacus recalculates unless Pulse has a matching evaluator.`,`Iterate bounded records or cells rather than duplicating the whole document in RAM. Each edition declares writable format versions; later Artemis features are not implicitly writable by the Z80 edition.${t.embedded_abacus_integration_id?' Embedded execution follows '+n.ref('abacus_embedding_id',t.embedded_abacus_integration_id,'Abacus-owned document API for embedded Pulse')+' rather than opening a second file writer.':''}`);}
function software(n,t){const id=n.r.id;
 if(id.startsWith('software_edition.abacus_')){
  if(id==='software_edition.abacus_3')abacus3(n,t);
  else{n.c('Spreadsheet and reporting model',id.includes('abacus_1')?'Abacus stores one sparse worksheet per document, with formulas and editor-consistent navigation. Spreadsheet data can populate printed forms and layouts.':'Abacus combines spreadsheet fields with report/document layouts containing text-mode horizontal or vertical bar charts and one-off or repeating sections.'+(t.artemis_native_extensions?' This native Artemis edition adds multiple tabs and cross-tab references.':''));n.c('File interchange and safe editing',`Pulse can edit supported closed Abacus files offline, preserving formulas and versioned features while excluding concurrent writers and invalidating stale cached results.`,`Versioned disk summaries from ${n.ref('accounting_export_id',t.data_interchange.export_definition_id,'BPI edition defining the imported accounting summaries')} supply independent planning inputs with named columns, account identifiers, period, currency, decimal amounts and reconciliation totals. Validate parsing, rounding, memory and save/reopen. This is not ledger write-back, live database access or simultaneous BPI execution.`);}
  portability(n,t);runtime(n,t);return;
 }
 if(id.startsWith('software_edition.pulse_')){n.c('Notebook and scripting role',id.endsWith('_1')?`Pulse implements ${n.ref('notebook_model_id',t.features_id,'Notebook language and document model implemented by this edition')}, organizing code as sequential sections that can be executed independently. It provides integer, string, Boolean and list values, loops, conditions and reusable functions for interactive work.`:'Pulse 3 is the native 32-bit Artemis development line, supporting standalone notebooks and offline editing as well as an embedded scripting runtime for Abacus 3.');pulseFiles(n,t);portability(n,t);runtime(n,t);return;}
 if(id==='software_edition.aionix'){n.c('System services and application compatibility',`AIONix implements ${n.ref('os_model_id',t.technology_id,'Operating-system service and process architecture')} and supplies the shared TUI runtime. Applications use ${n.ref('portable_api_id',t.portable_runtime.api_id,'Common application service API')} and ${n.ref('display_api_id',t.portable_runtime.display_id,'Display capability discovery')}; Business Tools consumes those system services rather than supplying another shared TUI library. Capability queries report available services, limits and usable displays.`,`Binary interfaces remain stable within the ERA target; the shared C API provides a separate source-portability path. Compatibility excludes undocumented hardware access, unqualified peripherals and unsupported interfaces, with no guarantee of unchanged speed or unlimited memory. Z80 software uses its separately qualified execution path. Publish ABI/API eligibility and tests, retain reference binaries and regression workloads, and fund engineering, runtime distribution and support before launch.`);runtime(n,t);return;}
 if(id==='software_edition.aionix_server'||id==='software_edition.cpm_aurelia_networking'){const server=id.includes('aionix');n.c('Network services and system continuity',server?'This complete system cartridge combines base AIONix process, file, device and TUI services with TCP/IP support, service lifecycle control and server administration. It is not an incremental base-system upgrade.':'The Aurelia extension adds a TCP/IP stack, negotiated-rate adapter driver, network configuration tools and the BPI client networking API. It retains the underlying CP/M platform services.',`Both optional services and inherited C/TUI interfaces use versioned capability checks. The driver implements ${n.ref('link_protocol_id',t.network_link_policy.link_layer_id,'Adapter rate negotiation and receiver-credit protocol')}: enforce host ceilings, distinguish advertised and negotiated rates, process packet interrupts/credits and expose fallback/error diagnostics. TCP/IP payload throughput is below the shared raw line rate and must be measured.`);runtime(n,t);return;}
 if(id==='software_edition.aionix2'){aionix2(n,t);runtime(n,t);return;}
 if(id==='software_edition.cpm_aurelia'){cpm(n,t);runtime(n,t);return;}
 if(id==='software_edition.cpm_model_ii'){n.c('Model II system adaptation','The edition supplies Model II boot, disk and printer BIOS services together with a native display/keyboard TUI adapter, bounded clipboard and required application services.');runtime(n,t);return;}
 if(id.startsWith('software_edition.bpi_suite')){n.c('Accounting modules and implementation',`The suite is implemented in AION C around a relational base engine, the Logix TUI and native FlexiBUS printing. General Accounting covers ledger, simplified receivables/payables, payroll integration and balance sheets. Accounts Receivable tracks customers, open invoices, payments and statements; Accounts Payable tracks vendors, liabilities, cash-flow obligations and cheque printing. Inventory Control handles stock, purchase orders, movement journals and profitability. Payroll handles employee hours, local/federal withholding, benefits and payroll cheques.`);n.c('Planning-data export',`Selected balances or monthly totals are exported as versioned delimited text with named columns, period, currency, account identifiers, decimal amounts and control totals. Close BPI before loading Abacus to use these as independent planning inputs; there is no automatic write-back, simultaneous execution or live database link. Reconcile counts/totals and test rounding, quoting, disk-full handling, memory and save/reopen; label prepared demonstration data.`);portability(n,t);runtime(n,t);return;}
 if(id.startsWith('software_edition.bpi_client_server')){bpiNetwork(n,t);portability(n,t);runtime(n,t);return;}
 if(id.startsWith('software_edition.business_tools_')){const aurelia=id.endsWith('_aurelia');n.c('Desktop applications and shared services',aurelia?'Business Tools supplies a text editor, disk browser, calculator and calendar/scheduler. Each application owns its documents, calculations or records while calling system screen, editing, list, form, clipboard and file services.':'The Artemis suite provides a file explorer, contact book, calendar/scheduler, task manager, text editor, calculator and chat.',aurelia?`Reusable widgets, input/screen primitives, clipboard ownership and workspace entry/return belong to ${n.ref('system_tui_id',t.system_dependencies[0].software_id,'System cartridge owning the shared TUI services')}. The application cartridge keeps its own logic and avoids a second shared TUI library. It retains a 16 KiB physical capacity and one cartridge position alongside the system cartridge; removing duplicate code does not establish a measured free-space budget. Code can execute from banked ROM while writable state and any resident workspace consume explicitly reserved RAM; residence does not imply multitasking.`:'Application code is supplied in the Business Tools/Office Suite expansion cartridge.');portability(n,t);runtime(n,t);return;}
 if(id==='software_edition.simple_c_z80'||id==='software_edition.aion_c_ide'){compiler(n,t);runtime(n,t);return;}
 if(id==='software_edition.aurelia_sdk'||id==='software_edition.artemis_sdk'){const a=id.includes('aurelia');n.c('Platform development kit',`The kit combines the ${a?'Aurelia':'Artemis'} technical reference and programmer’s manual with video, expansion-card, FlexiBUS and cartridge guides. It supplies headers, bindings, target libraries, startup code, examples, small utilities and tests; the compiler/IDE is a separate tool.`,`Documentation covers the portable C/ABI contract, Logix API v1 and service discovery, capability-driven display/TUI operation, portable file formats, memory handles, resource budgets and target conformance. Examples exercise 40/80-column and monochrome interfaces.${a?' Additional material covers physical-bank DMA, refresh/arbitration, upload ports, abort handling and dedicated sprite SRAM with atomic descriptor-bank changes.':''}`);runtime(n,t);return;}
 if(id==='software_edition.microsoft_basic_aurelia'){n.c('Licensed BASIC implementation','This licensed third-party BASIC was developed in cooperation with AION for Aurelia CP/M. It uses the shared Logix TUI and capability-discovery interfaces; that integration does not imply that the BASIC implementation itself is portable C.');runtime(n,t);return;}
 if(id==='software_edition.aurelia_compatibility_kit'){compatibilityKit(n,t);runtime(n,t);return;}
 if(id.startsWith('software_edition.aion_development_team')){team(n,t);runtime(n,t);return;}
 if(id.startsWith('software_edition.entertainment_suite')){n.c('Games and input practice',`The suite includes ${n.p('games',['Sudoku','Solitaire (Klondike)','Spider','FreeCell'])} and tutorials for pointing, clicking, dragging and both scrolling rollers. Keyboard alternatives, undo and clear rules remain available.`,`Standard TUI/display and pointing APIs use colour to distinguish suits and selections while retaining monochrome patterns and labels. Older supported monitors remain usable, and the 64 KiB graphics card is not required. Validate puzzle validity/uniqueness, legal moves, deals, undo, input and resource budgets; random card deals are not all guaranteed solvable.`);runtime(n,t);return;}
 if(id==='software_edition.autocad_1_artemis'){n.c('Native CAD workflow',`AutoCAD provides native 2D CAD with typed coordinates and validated numerical geometry, separate command/status and 800 × 600 drawing displays, explicit Logix Mouse input, professional line/blit acceleration, drawing interchange and supported pen-plotter output. ${n.ref('launch_package_id',t.specification.comdex_offering_id,'Commercial package supplying this AutoCAD implementation')} packages the implementation; Autodesk retains ownership and non-exclusive cross-platform rights.`);n.c('Development and shipping qualification','The sponsored development environment uses Artemis PRO workstations with 1 MiB RAM and qualified storage, plus shared server/test capacity. Measure the shipping minimum against representative drawings; development equipment does not qualify base 128/256 KiB Artemis automatically.');runtime(n,t);return;}
 throw Error('No software narrative for '+id);
}
function abacus3(n,t){n.c('Worksheets, structured tables and reports','Abacus 3 is the native 32-bit Artemis spreadsheet and analysis line. Sparse worksheets and schema-defined formatted-table tabs coexist with multiple tabs, cross-tab references, typed columns, virtual calculated columns, unique-key lookups and a documented read-only SQL subset. Disk-backed columnar storage uses column pruning, conservative statistics-based skipping and dataset-dependent encoding rather than promised compression or throughput.',`Reports extend earlier spreadsheet-field layouts with one-off/repeating sections and graphical ${n.p('chart_types',t.reporting.chart_types)} charts. Capability-aware preview includes titles, axes and legends while retaining standard TUI editing and monochrome patterns. Supported printer drivers paginate output; refresh stale query/formula results before printing.`);
 n.c('Scripting and data interchange','Embedded Pulse uses the Abacus-owned document API; standalone Pulse retains exclusive offline access to supported closed files. Preserve formulas and invalidate changed cached results rather than allowing a second concurrent writer.','Versioned BPI summaries remain independent planning inputs with decimal checks and reconciliation, without ledger write-back or a live database link. CSV import maps schemas, quoting, delimiters, encodings, dates, decimal conventions, nulls and text identifiers, with rejected-record diagnostics. Value-only export explicitly loses formulas and types.','VSAM import consumes host-exported sequential logical records, for example through IDCAMS REPRO, with a supplied record layout and transfer path. Declare boundaries, lengths, offsets and keys; convert EBCDIC, supported binary, packed decimal and zoned decimal explicitly. Raw VSAM images, clusters and indexes are not desktop interchange files. Reject unsupported layouts without reinterpretation. Preserve older document versions; older Abacus/Pulse editions must reject unsupported new features before writing.');
 n.c('Release scope and acceptance','The initial release uses flat formatted tables. Bounded nested arrays/maps/structs with explicit aggregation/expansion and broader Lotus 1-2-3 response features are later work. It does not promise background recalculation, unlimited documents/memory, a full transactional SQL database, arbitrary VSAM image access or unrestricted nested data.','Qualify actual Artemis 128/256 KiB and later PRO configurations separately. Measure memory, storage, timing, I/O and compression on named datasets; larger jobs may need expansion or disk-backed processing. Exercise sales import, customer/product joins, margins, regional grouping, printed charts, save/reopen and the equivalent Pulse script. Check conversions, rounding, nulls, duplicate keys, join cardinality, cancellation, grouped undo, visibility, dependency invalidation, recovery and unsupported-version rejection. No unmeasured minimum RAM or maximum row count is asserted.');}
function compiler(n,t){const native=n.r.id==='software_edition.aion_c_ide',x=t.toolchain;
 n.c('Compiler and build targets',native?`The C compiler, optimizer and IDE implement ${n.ref('portability_framework_id',t.technology_id,'Framework for shared source and isolated target builds')}. Native ERA and cross-Z80 backends use separate target libraries, startup code, output directories and build profiles; a Z80 build cannot link AIONix-only or host libraries.`:`The toolset implements ${n.ref('language_contract_id',x.language_contract_id,'Portable C language and target ABI contract')} with ${n.ref('runtime_contract_id',x.runtime_contract_id,'Shared C/TUI/graphics service contract')}. It supports structures, typedef, function pointers, documented 32-bit integer arithmetic and shared string/stream-I/O behaviour. The toolchain combines a Z80 compiler backend, assembler, linker, CP/M startup, target runtimes and ROM/cartridge image tools.`, `Build profiles are ${n.p('build_profiles',x.profiles)} for ${n.p('build_targets',x.targets)}. ROM-aware linking generates disk or cartridge images, with RAM/ROM/stack budget reports and portability diagnostics.`);
 n.c('Development and conformance',native?'Edit the shared project on Artemis, select a target, compile/link with its libraries, inspect resource requirements, package the target image and run conformance/application regressions. Shared libraries and templates support adaptation to multitasking C, but emulation and remote execution/debugging on physical Aurelia are optional development features.':'Test 48 KiB and 64 KiB installed-RAM profiles, including reserved common RAM and resident workspace.','Display regressions cover 40-column, 80-column and monochrome layouts. Each target keeps its own assembler/linker, startup and runtime; shared source is not interchangeable binaries.');}
function bpiNetwork(n,t){const a=t.architecture,d=t.specification.implementation_design,server=n.r.id.endsWith('era_server');
 n.c(server?'Transaction server':'Thin accounting client',`${server?'This edition executes':'This edition sends bounded business operations to'} the relational accounting service on ${n.ref('server_host_id',a.server,'Host executing database and transaction work')}${!server?' running '+n.ref('server_edition_id',a.server_edition_id,'Server implementation used by this client'):''}. Queries, indexes, validation, posting and transactions stay server-side; clients receive bounded pages of forms/results rather than arbitrary database pages or whole tables. ${n.ref('network_stack_id',a.network_id,'Transport stack used by the accounting protocol')} supplies the network path. Robustness and capacity remain acceptance targets.`);
 n.c('Commit, recovery and duplicate protection','Version 1 serializes writers with short transactions and bounded reader locks; editing a form must not hold an interactive transaction open. Redo after-images carry transaction ID, sequence, length and checksum; a commit marker covers record count and checksum. Force log and commit marker to durable storage before acknowledging, then apply/replay changes idempotently. Persist request IDs and outcomes in the same transaction so a lost acknowledgement can be retried without posting a payment twice.','Uncommitted data must not reach database files; transaction size is limited by buffers. Checkpoint into replacement pages/indexes, force them, then alternate checksummed generation-numbered roots. Retain the previous valid root and required redo log until the new checkpoint is durable. Startup validates checksums and exposes only committed work. Torn-write safety and disk/controller completion semantics must be proven; no battery-backed cache is assumed.');
 n.c('Protocol and operational limits',`Length-framed TCP requests use ${n.p('request_fields',d.protocol.fields)}. Operations are ${n.p('operations',d.protocol.operations)}; messages and streamed results are bounded. Reconnecting clients query status or reuse the original durable request ID.`, 'Amounts use explicit scaled-integer/decimal rules with currency, rounding, posting dates, periods and unique document IDs. Cross-module postings are atomic and append an audit record. Backups capture a consistent checkpoint and required logs, with restoration tested on a clean disk. Bound log growth, handle full disks and expose recovery status.',`The server target is ${n.p('server_ram_kib',d.initial_limits.server_ram_kb)} KiB with ${n.p('concurrent_sessions_target',d.initial_limits.concurrent_sessions_target)} concurrent sessions. Plan backups/reports around the negotiated shared 100/250/500/1000 kbit/s raw LAN budget and measured payload throughput; the slowest admitted host limits the common rate. Test power loss around acknowledgements, duplicate retries, concurrent postings, disk-full/corrupt-log failures, backup restoration and a 48 KiB Aurelia client.`);}
function cpm(n,t){n.c('CP/M services and Logix extensions',`The system adapts ${n.p('base_version',t.base_version)} for banked-ROM execution while preserving standard entry points, loading conventions and available-memory boundaries. A single foreground application can use ordinary CP/M console/file services; richer behaviour uses the separate versioned Logix API.`,`The CCP interprets commands and loads disk/cartridge programs; BDOS supplies file services through the machine BIOS, which adapts calls to Logix drivers. Motherboard ROM supplies ${n.p('firmware_contents',t.components.mainboard_rom)}. The system cartridge supplies ${n.p('cartridge_contents',t.components.system_cartridge)}; command buffers and mutable system state remain in RAM. ROM constants/code must be separated from state and self-modifying routines adapted.`);
 n.c('Addressing, startup and device access',`In conventional CP/M, 0000H–00FFH holds vectors, default file-control data and the command/disk buffer. Programs load at ${n.p('program_load_address',t.vanilla_architecture.program_load_address)} in the transient program area and call BDOS through ${n.p('bdos_entry',t.vanilla_architecture.application_entry)}; CCP, BDOS and BIOS occupy higher memory. The TPA is application RAM, not an OS module. Transient editor/copy/assembler/debugger/maintenance utilities load when needed.`,`Compared with 1.3, the 1.4 base supports four logical drives, BIOS sector translation and extra drive state; BDOS begins one 256-byte page lower while CCP/BIOS bases stay fixed. It revises disk errors, returns DE consistently with HL and splits BDOS into PL/M logic plus an assembly interface. Vanilla 1.4 does not contain Logix banked-ROM, cartridge, dynamic-driver, TUI/clipboard/workspace services or the later CP/M 2.0 disk-parameter-block model.`,`Logix boot firmware discovers cartridges and provides diagnostics/recovery. The common-memory runtime preserves accessible entry code, stack and interrupt state across nested bank switches, following ${n.ref('memory_model_id',t.memory_discovery_id,'Bank mapping and discoverable RAM contract')}. Drivers in motherboard/device ROM or extensions register video, keyboard, floppy and FlexiBUS services. BIOS and relevant BDOS assumptions must match Aurelia disk formats. DMA uses physical-bank descriptors, bounded transfers and ready handshakes; drain or abort it before warm boot or buffer reuse. Video uploads expose dedicated sprite SRAM and atomic descriptors with backpressure, falling back to programmed I/O where needed.`);
 n.c('Shared TUI ownership and application behaviour',`The system owns ${n.ref('tui_contract_id',t.tui_ownership.interface_id,'Shared screen, input, clipboard and workspace service contract')}, exposed through ${n.ref('portable_api_id',t.portable_runtime.api_id,'Shared C interface')} and ${n.ref('display_api_id',t.portable_runtime.display_id,'Display capability discovery')}. It supplies reusable controls, while ${n.refs(t.tui_ownership.consumers,'Application consuming system-owned TUI services','consumer_')} retain their document, calculation, file-management and scheduling logic.`,`Screen services query usable dimensions, clip/scroll and distinguish document from display coordinates. Compact 40-column and expanded 80-column layouts fit dialogs, names and errors; semantic text/selection/warning roles map to colour or monochrome. Structured character, function/navigation and modifier events support blocking or polled input. Shared fields, lists, menus, forms, popups and focus movement use consistent editing and clipboard commands. Clipboard formats, lengths, capacity, ownership and errors are explicit. Contexts are created/destroyed and activated/deactivated with redraw; one may cover the whole screen. System timing and repeat replace CPU-speed loops.`,`Sequential applications can use these services without multitasking. Exact widgets, clipboard capacity and workspace reservations remain implementation choices. Preserve legacy console behaviour and stable target ABI, use capability discovery, and avoid hard-coded stride, video addresses, last columns or hardware registers. The same documented API spans Aurelia, Aurelia+ and Artemis; Artemis mediates shared display/clipboard access between processes.`);}
function aionix2(n,t){const s=t.specification,m=t.architecture.resource_planning;
 n.c('System architecture and release boundary',`AIONix2 develops ${n.ref('baseline_os_id',s.baseline_id,'Inherited AIONix service architecture')} for ${n.ref('processor_architecture_id',s.processor_architecture_id,'Protection and execution architecture used by the OS')}, retaining ${n.ref('portable_api_id',s.portable_api_id,'Portable C and UI service interface')}. The initial release combines executable system ROM, documented legacy ABI compatibility, protected preemptive user processes, recoverable HDD storage, users/permissions, a POSIX-oriented subset and an event-driven TUI foundation.`,`ROM execution/ABI, resilient multitasking and recoverable storage are essential, followed by access enforcement and the staged interface/UI work. Paging, metadata journaling, broader networking, threads/locales and a full windowed GUI remain later work, not initial release gates. These are engineering priorities rather than completed qualification.`);
 n.c('ROM execution, compatibility and memory',`Stable kernel code, core libraries, a small shell/basic utilities and recovery tools share read-only, cacheable executable ROM; each process keeps writable state in DRAM. The replaceable system cartridge supplies at least ${n.p('minimum_os_rom_bytes',m.minimum_os_rom_bytes)} bytes. EEPROM BIOS remains boot/diagnostic firmware; optional services, larger utilities and patches load from disk rather than copying the entire ROM into RAM.`,`Executable ABI versions select legacy adapters, stable library dispatch and capability discovery. Preserve documented ERA instruction semantics, C calling conventions and layouts, syscall entry/numbers, loading, errors and legacy signals. Privileged drivers, undocumented kernel assumptions and direct hardware access need separate qualification; Z80 C code must be recompiled. Versioned dispatch and page-sized RAM overlays patch code after ROM checksum/version checks, with recovery boot bypassing disk patches. A qualified minor revision can be installed by exchanging a host-compatible cartridge.`,`The preferred DRAM allocation is ${n.p('preferred_dram_bytes',m.preferred_dram_bytes)} bytes; the 256 KiB minimum is an engineering fit target, not a measured guarantee, and the server retains its existing 1 MiB configuration. Illustrative allocations are 40 KiB for kernel state/tables/stacks, 24 KiB for filesystem buffers, 16 KiB for translation metadata, 12 KiB for terminal/UI input, 20 KiB for services/patch reserve and 144 KiB for applications. Shared ROM, sparse page tables, small kernel stacks and reliable copy-on-write reduce demand. Allocation failure must be handled; ROM cannot replace writable RAM. Later swap requires qualified restart, locking and I/O with fault handlers resident, and should address occasional pressure rather than routine oversizing.`);
 n.c('Scheduling, protection and process lifecycle','A compact monolithic kernel timer-preempts user processes while bounding non-preemptible kernel critical sections. Priority aging, sleeping I/O and atomic sleep/wakeup provide fairness; short interrupts defer work. Validate user pointers, protect kernel/device mappings, constrain per-process memory/files/requests, bound driver retries and timeouts, and retain responsive administrative termination. Process exit cleans files, memory, locks and child state. Kernel-controlled DMA uses checked pinned buffers; process isolation alone protects neither kernel/driver faults nor DMA. A fully preemptible kernel and application threads are not initial requirements.');
 n.c('Filesystem, durability and access control',`A versioned inode filesystem separates directory entries from metadata, using ${n.p('allocation_block_bytes',s.filesystem.allocation_block_bytes)}-byte blocks and ${n.p('block_identifier_bits',s.filesystem.block_identifier_bits)}-bit block IDs. The initial qualification range is ${n.p('qualification_volume_mb',s.filesystem.initial_qualification_volume_mb.join('–'))} MB, not a capacity ceiling or bundled-drive change. Direct/indirect pointers, metadata timestamps/link counts, bounded caches, mounts and logical-sector drivers with CHS translation support the layout.`,`Clean/dirty state, a consistency checker, ordered metadata writes, explicit synchronization and tested backup/restore establish recoverability. Exact disk format/limits, file-offset and timestamp representation, legacy import/mount behaviour and controller persistence guarantees remain open. A later small metadata journal still needs power-loss/write-order testing and does not alone ensure application-data durability.`,`Numeric users/groups, owner/group/other permissions including directory search, creation masks, real/effective credentials and login/home directories define access. Protect salted, costed password hashes within CPU budgets and enforce permissions on every relevant kernel operation. Device/mount/configuration administration and audit records are protected. Qualify credential/exec transitions before enabling set-user-ID programs; servers authenticate users rather than trusting supplied UIDs. Extended ACLs are later work.`);
 n.c('Unix-style interface direction','The initial subset defines file/descriptor operations and errors; descriptor duplication/inheritance; copy-on-write fork, exec, wait, status and environment; signals/masks/dispositions and interruption; canonical/raw terminals and foreground process groups; hierarchical paths, working directories and hard/symbolic links; pipes, EOF/broken-pipe handling and readiness multiplexing; shell quoting, redirection, pipelines, variables and statuses; wall and monotonic clocks with explicit timestamp formats. Publish an implemented/partial/absent matrix and unsupported-operation errors rather than claiming conformance from names. Efficient spawn, broader file control/mapping, full job control/pseudo-terminals, sockets/IPC, utilities, locales, threads and timers are later additions.');
 n.c('Event-driven user interface','Applications own business logic and semantic Open/Save/Select/Cancel commands. A shared abstraction provides events, menus, forms, lists, focus, layout, measurement and drawing contexts; translation adapters preserve TUI, terminal, device and legacy ABI behaviour above native process/file/IPC/timer/input/display services. These are logical library/service layers, not four mandatory processes or IPC hops.','A bounded event queue handles keys, timers, focus, redraw and future pointer events. Opaque view/window handles initially describe text regions; clipping, invalidation, repaint, layout constraints and text measurement use separate cell/pixel coordinates. Clipboard/selection ownership is bounded, and graphics/font/colour/pointer support is discovered by version and capability. Compact text state, dirty regions and redraw callbacks avoid a mandatory full-screen backing bitmap. A later GUI can host old character applications in terminal windows without automatically redesigning them.');
 n.c('Acceptance evidence','Release tests must cover legacy binary regressions, fairness/termination under CPU load, injected faults and cleanup, concurrent disk/terminal/DMA I/O, power loss and durable saves, credentials/permissions, measured ROM/RAM use with Abacus/compiler/server workloads, and TUI fallback/legacy terminal behaviour.');}
function compatibilityKit(n,t){n.c('Published compatibility environment','The kit documents released 8-bit Aurelia processor, CP/M, memory, display, keyboard, storage and error-behaviour contracts. It supplies runtime-adapter source and redistribution terms, diagnostics and failure/resource-limit tests, plus Abacus/Business Tools workloads for calculation, interchange, printing and save/reopen. Manuals, source listings, machine-readable disks and versioned result forms support independent implementations.','Any manufacturer or integrator can implement the environment without a bespoke partnership or mandatory certification. Existing Z80 binaries need compatible instructions and OS/runtime/memory behaviour; CP/M alone is insufficient, and another processor needs a port or execution solution. Native video, keyboard, disk and printer interfaces may use adapters; FlexiBUS and Logix video are separate optional profiles, including applicable terms for hardware clones.');n.c('Qualification and distribution','Named supported platforms are tested configurations, not an exclusive permission list for properly licensed applications. Optional certification applies to an exact configuration/version and distinguishes a manufacturer’s claim from AION-tested application compatibility; FlexiBUS electrical/protocol and Logix display claims are separate. Printed documentation/source listings accompany disks; host/media conversion is a separate delivery requirement.');}
function team(n,t){const server=t.role==='team_server',z80=t.execution_target==='z80_cpm';
 n.c(server?'Shared development repository':'Developer workspace',`${server?'The server stores':'The client accesses'} atomic multi-file commits with authors, dates, messages, branches, release labels, diffs, rollback and comments tied to immutable revisions. Workspaces are isolated: saving a file does not commit it. Text channels, posts/replies, file/revision/commit links, calendars, meetings, invitations, tasks, owners, deadlines and milestones support collaboration.`,`${z80?'The Aurelia client uses compact TUI tools and sequential CP/M overlays; the complete suite is not assumed resident in 48 KiB.':'Artemis supports local ERA/Z80 builds.'} Heavy or ERA work can be queued on the server; Aurelia/Aurelia+ retain local Z80 tools. Breakthru TUI adapters and separate target binaries, startup and libraries serve CP/M/Z80 and AIONix/ERA. Reproducible builds record source revision, compiler version, settings and target libraries. Apple and Commodore packages are future work, without launch or binary-compatibility claims.`);
 n.c('Storage, networking and acceptance','The server baseline is Artemis PRO with 1 MiB recommended RAM. The existing 5 MB disk supports bounded pilots only; archive old history, rotate external floppy backups and qualify larger storage for substantial projects. It is not included in the software definition. Network transfers are bounded, saves acknowledged and workspaces recoverable after disconnect. Four concurrent developers is a validation target, not measured throughput. Gate release on commit recovery, access control, backup/restore, conflicts and both target regression suites.','Sponsored deployments must supply and qualify their own workstation/server capacity, storage, concurrency and dedicated support. This engineering requirement does not change retail entitlement.');}
function reviseModes(modes){return (modes||[]).map(m=>{
 const p=new Map(m.parameters.map(p=>[p.key,p]));
 let description=m.type==='text'?'The {columns} × {rows} character grid occupies {width} × {height} logical pixels, using {glyph_width} × {glyph_height}-pixel glyphs. One page reserves {framebuffer_size} bytes, including {character_map_bytes_per_buffer} bytes for character codes and {attribute_map_bytes_per_buffer} bytes for attributes. The {character_count}-character font occupies {font_bytes} shared bytes; it is separate from each page. Attributes encode {attribute_format}.':'The bitmap contains {width} × {height} pixels at {bits_per_pixel} bits per pixel. Its scanline stride is {stride_bytes} bytes and one framebuffer occupies {framebuffer_size} bytes.';
 description+=' '+(m.double_buffering===true?'Double buffering is supported within the recorded memory allocation.':m.double_buffering===false?'The recorded allocation does not support double buffering.':'Double-buffering capability remains unspecified.');
 if(m.sprites_available!==null)description+=' The independent sprite store keeps {sprites_available} sprites available.';
 if(p.has('framebuffer_count'))description+=' The {framebuffer_count}-buffer layout reserves {palette_list_bytes} bytes for the palette list and leaves {remaining_bytes} bytes unused; it supports {simultaneous_values} simultaneous pixel values.';
 if(p.has('inherited_from_id'))description+='\n\nGeometry and baseline buffering are inherited from {inherited_from_id}. The professional display centers older modes in its fixed 800 × 600 raster without scaling. Qualify monitor support, palette allocation and sprite timing; the source board’s allocation totals do not describe the professional board.';
 else{
  const paragraphs=m.description.split(/\n\s*\n/).filter(x=>x.startsWith('The original mode requires')||x.startsWith('The recorded allocation')||x.startsWith('The five legacy sprites'));
  if(paragraphs.length)description+='\n\n'+paragraphs.join(' ');
 }
 if(m.description.includes('Compatibility mode is enabled'))description+=' This is a compatibility mode.';
 const used=new Set([...description.matchAll(/\{([^{}]+)\}/g)].map(x=>x[1]));
 for(const key of p.keys())if(!used.has(key))throw Error(m.id+': unhandled graphics parameter '+key);
 return {...m,description};
});}
const draft=structuredClone(original),audit={basis_commit:'be82628',feedback_id:'change_review.b3835106-483c-4736-937b-bfedc7e0ab78',method:'Authored narratives by component/application purpose. No generic property traversal or generated fallback prose.',records:[],excluded_legacy_nontechnical_content:['Team editions: adoption pricing and commercial package/support terms were not copied into technical specifications. Legacy definitions remain unchanged for step 5.','CP/M internal component IDs and diagram labels are presentation identifiers; responsibilities, location and call relationships are described in prose.','AIONix2 ordinal planning labels are summarized as release priorities and qualification conditions, not technical parameters.','A record does not reference itself merely to restate its own identity.','The Artemis NIC omits the unrelated Aurelia CPU-clock service example; those budgets remain with the Aurelia adapter. Both retain the applicable bounded packet-service requirement.','Socket groups are retained exclusively at the composition-version level, with their contents unchanged.']};
